(async () => {
  const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
  const s = window.__toolboxStore;
  const out = {};

  // 找一件带自定义元件的作品打开（用前面测试建的那个）
  let card = [...document.querySelectorAll('.tb-project-main')].find((c) => (c.innerText || '').includes('传播测试项目'));
  if (!card) card = document.querySelector('.tb-project-main');
  out.work = (card?.innerText || '').split('\n')[0];
  card?.click();
  await sleep(3000);

  // 打开分享弹层 → 生成分享页，抓 HTML
  let captured = null;
  const orig = URL.createObjectURL.bind(URL);
  URL.createObjectURL = (b) => { captured = b; return orig(b); };
  [...document.querySelectorAll('.pj-head-actions button')].find((b) => b.textContent.includes('分享作品'))?.click();
  await sleep(1500);
  [...document.querySelectorAll('.sw-btn')].find((b) => b.textContent.includes('生成分享页'))?.click();
  for (let i = 0; i < 20 && !captured; i++) await sleep(500);
  URL.createObjectURL = orig;
  out.gotHtml = !!captured;
  const html = captured ? await captured.text() : '';
  out.htmlBytes = html.length;

  // 分享页里内嵌的作品文件（var ECP = "base64"）是不是也带着快照
  const m = html.match(/var ECP = ("[A-Za-z0-9+/=]{100,}"|null);/);
  out.embedded = !!m && m[1] !== 'null';
  if (out.embedded) {
    const bin = atob(m[1].slice(1, -1));
    out.zipBytes = bin.length;
    out.hasSnapshotEntry = bin.includes('components_snapshot.json');
    out.hasSnapshotId = bin.includes('xyz-module');
    out.hasLibImage = bin.includes('lib_xyz-module.png');
    out.leaksCredential = /sk-[A-Za-z0-9]{6,}|api[_-]?key|ai_config/i.test(bin);
  }
  return JSON.stringify(out);
})()
